function switchTab(tab){closeDrawer(false);state.tab=tab;state.context=tab==='virtual'?'virtual':'list';$$('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));tab==='virtual'?renderVirtual():renderList();renderNotes();}
function makeDraft(){return {type:'MCU固件',channel:'',functionVersion:'开发中版本 - 未上架',method:'NONE',file:null,parsed:null,upload:'empty',appRule:'不限',appVersion:'',note:'',busy:false};}
