function parseName(name){const m=/^([^_]+)_([^_]+)_(\d+(?:\.\d+)*)_([^_]+)_([^_]+)_(\d{8})\.(ufw|zip|bin)$/i.exec(name);return m?{company:m[1],project:m[2],version:m[3],hardware:m[4],code:m[5],date:m[6],ext:m[7],name:`${m[2]} ${draft?.type||'MCU固件'}`} :null;}
function updateParsed(){const p=draft.parsed;$('#parsedInfo').innerHTML=[['固件名称',p?.name],['固件版本',p?.version],['硬件版本',p?.hardware],['公司 / 项目',p?`${p.company} / ${p.project}`:''],['校验码（文件名片段）',p?.code],['日期 / 格式',p?`${p.date} / ${p.ext}`:'']].map(([a,b])=>`<div class="parse-item"><span>${a}</span><strong>${esc(b||'—')}</strong></div>`).join('');}
async function selectFile(file){if(!draft||draft.busy)return;const d=draft;const token=++uploadToken;d.file=file;d.parsed=parseName(file.name);d.upload='empty';$('#fileError').textContent='';$('#fileCurrent').className='file-current';$('#fileCurrent').textContent=file.name;updateParsed();if(!d.parsed){$('#fileError').textContent='文件名或格式不符合规范，请按命名示例重新选择。';d.upload='failed';return;}d.upload='uploading';$('#fileCurrent').innerHTML=`<span class="loading-dot"></span>正在上传 ${esc(file.name)}`;await new Promise(r=>setTimeout(r,450));if(token!==uploadToken||d!==draft||state.context!=='create')return;if(state.failure==='upload'){d.upload='failed';$('#fileCurrent').textContent=file.name;$('#fileError').textContent='上传失败，请重新选择文件。';}else{d.upload='done';$('#fileCurrent').classList.add('success');$('#fileCurrent').textContent=`${file.name} · 上传成功`;}}
function createError(text){const el=$('#createError');el.textContent=text;el.hidden=false;el.scrollIntoView({block:'nearest'});}
async function submitCreate(){const d=draft;if(!d||d.busy)return;$('#createError').hidden=true;if(!d.file||!d.parsed||d.upload!=='done'){createError(d.upload==='uploading'?'文件上传中，请稍后创建。':'请先上传符合规范的固件文件。');return;}if(d.type==='MCU固件'&&d.channel&&!/^[1-9]\d*$/.test(d.channel)){createError('通道号须为正整数，或留空。');return;}if(d.appRule!=='不限'&&!/^\d+(\.\d+)*$/.test(d.appVersion.trim())){createError('请填写有效的 APP 版本号，例如 2.2.10。');return;}if(rows.some(r=>r.type===d.type&&r.hardware===d.parsed.hardware&&r.version===d.parsed.version)){createError('已存在相同固件（固件类型、硬件版本与固件版本相同）。');return;}
d.busy=true;$('#submitCreate').textContent='创建中…';$$('.drawer button,.drawer input,.drawer select,.drawer textarea').forEach(e=>e.disabled=true);await new Promise(r=>setTimeout(r,400));if(state.failure==='submit'){d.busy=false;$$('.drawer button,.drawer input,.drawer select,.drawer textarea').forEach(e=>e.disabled=false);$('#submitCreate').textContent='创建';createError('创建失败，请稍后重试。已保留本次输入。');return;}
const p=d.parsed;const row={id:`f${++seq}`,name:p.name,type:d.type,version:p.version,hardware:p.hardware,channel:d.type==='MCU固件'?d.channel:'',method:d.method,digest:'',file:d.file.name,fileObject:d.file,status:'开发中',date:'2026-11-11 10:30',note:d.note||'—',appRule:d.appRule,appVersion:d.appVersion,functionVersion:d.functionVersion};rows.unshift(row);draft=null;state.query='';state.type='all';renderList();openDetail(row.id);showToast('固件创建成功');if(row.method!=='NONE'&&state.backend==='auto')setTimeout(()=>returnBackendDigest(row),2500);
}
async function computeDemoDigest(row){const fixture=fixtureByName(row.file);if(['127.0.0.1','localhost'].includes(location.hostname)&&location.port==='8767'){try{const blob=row.fileObject||new Blob([fixture?.content||'']);if(!row.fileObject&&!fixture)throw new Error('No fixture');const res=await fetch(`/__prototype__/digest?method=${encodeURIComponent(row.method)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:blob});if(res.ok){const body=await res.json();return body.digest;}}catch(e){/* Standalone fallback uses exact built-in sample bytes only. */}}
if(fixture&&!row.fileObject)return row.method==='MD5'?fixture.md5:fixture.sha256;
if(fixture&&row.fileObject){const exact=await row.fileObject.text();if(exact===fixture.content)return row.method==='MD5'?fixture.md5:fixture.sha256;}
throw new Error('请使用本地演示服务计算任意上传文件摘要；当前记录已创建，摘要不伪造。');}
async function returnBackendDigest(row){if(!row||row.method==='NONE')return;if(state.backend==='fail'){showToast('演示：后端未取得摘要，方法保持不变。',true);return;}try{const digest=await computeDemoDigest(row);if(!rows.includes(row))return;row.digest=digest;if(state.context==='detail'&&state.editing===row.id){updateDetailDigest(row);}showToast('演示：已收到后端摘要结果');}catch(e){showToast(e.message,true);}}
function detailBody(r){return `<div class="detail-grid"><div class="form-section">基础信息</div>${[['固件名称',r.name],['固件类型',r.type],['固件版本',r.version],['硬件版本',r.hardware],...(r.type==='MCU固件'?[['通道号',r.channel||'NULL']]:[]),['状态',r.status],['功能版本',r.functionVersion||'开发中版本 - 未上架'],['APP 版本号',`${r.appRule}${r.appVersion?' '+r.appVersion:''}`],['上传时间',r.date],['备注',r.note]].map(([k,v])=>`<div class="field"><label>${k}</label><div class="control value">${esc(v)}</div></div>`).join('')}<div class="form-section spaced" data-anchor="09">文件信息 ${badge('09')}</div><div class="field"><label>固件文件</label><div class="control value">${esc(r.file)}</div></div><div class="field" data-anchor="10"><label>校验方法 ${badge('10')}</label><div class="control value"><span id="detailMethod">${methodName(r.method)}</span><p class="hint" id="detailDelivery">${methodDescription(r.method)}</p></div></div><div class="field"><label>文件摘要</label><div class="control"><div class="digest" id="detailDigest">${esc(r.method==='NONE'?'—':r.digest||'—')}</div><p class="hint" id="detailHint">${digestHint(r)}</p></div></div><div data-anchor="11" class="hint">历史固件默认无需校验 ${badge('11')}</div></div>`;}
function digestHint(r){return r.method==='NONE'?'旧桶裸链，无包校验和下载 token 验证。':r.digest?'摘要来自后端计算的完整文件内容。':'暂无后端摘要结果；当前方法不变，不代表校验通过。';}
function updateDetailDigest(r){$('#detailDigest').textContent=r.digest||'—';$('#detailHint').textContent=digestHint(r);}
function openDetail(id){const r=rows.find(r=>r.id===id);if(!r)return;state.context='detail';state.editing=id;state.appRecord=id;drawerShell('固件详情',detailBody(r),'<button id="closeDetail">关闭</button>');$('#closeDetail').onclick=()=>closeDrawer();renderNotes();wireAnchors();showDrawerPosition();}
function openMembers(){state.context='members';state.editing=null;drawerShell('虚拟版本 4.0.0',`<div class="notice" data-anchor="12">关联 3 个实体固件 · 引用已冻结 ${badge('12')}</div><div class="form-section" data-anchor="13">关联文件信息 ${badge('13')}</div>${['f2','f3','f1'].map(id=>{const r=rows.find(x=>x.id===id);return `<div class="member-block" data-member="${id}"><div class="member-head"><strong>${esc(r.name)} / ${r.version}</strong><span>通道 ${r.channel} · 硬件 ${r.hardware}</span></div><div class="member-body"><span>固件文件</span><span>${esc(r.file)}</span><span>校验方法</span><span>${methodName(r.method)}</span><span>下载策略</span><span>${methodDescription(r.method)}</span><span>文件摘要</span><div class="digest">${r.method==='NONE'?'—':r.digest||'—'}</div></div></div>`;}).join('')}`, '<button id="closeMembers">关闭</button>');$('#closeMembers').onclick=()=>closeDrawer();renderNotes();wireAnchors();showDrawerPosition();}
function closeDrawer(render=true){if(draft?.busy)return;uploadToken++;draft=null;$('#overlayHost').innerHTML='';state.context=state.tab==='virtual'?'virtual':'list';state.editing=null;if(render)renderNotes();}
function renderNotes(){$('#notesPane').scrollTop=0;const group=noteGroups[state.context];$('#noteContext').textContent=({list:'固件配置 / 固件版本',create:'创建固件 / 配置与提交',detail:'固件详情 / 文件信息',virtual:'固件配置 / 虚拟版本',members:'虚拟版本 / 关联文件信息'})[state.context];$('#noteCards').innerHTML=group.map(n=>{const d=noteDefs[n];return `<article class="note-card" id="note${n}" data-card="${n}" tabindex="0"><div class="note-title"><span class="note-number">${n}</span><span>${d.title}</span></div><div class="note-loc">关联位置：${d.loc}</div><div class="note-body">${d.body}</div></article>`;}).join('');$$('[data-card]').forEach(card=>{card.onclick=()=>selectNote(card.dataset.card,false);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectNote(card.dataset.card,false);}};});renderTools();}
function selectNote(n,scrollNotes=true){$$('.annotation-target').forEach(el=>el.classList.remove('annotation-target'));$$('.note-card').forEach(el=>el.classList.toggle('selected',el.dataset.card===n));const target=$(`[data-anchor="${n}"]`);if(target){target.classList.add('annotation-target');target.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});}const card=$(`#note${n}`);if(scrollNotes&&card)card.scrollIntoView({block:'nearest',behavior:'smooth'});state.selectedNote=n;}
function wireAnchors(){$$('[data-note]').forEach(b=>b.onclick=e=>{e.preventDefault();selectNote(b.dataset.note,true);if(innerWidth<=1000)setPane('notes');});}
function renderTools(){const create=state.context==='create',detail=state.context==='detail';$('#demoTools').innerHTML=`${create?`<label class="tool-label">填入演示文件（仅原型）</label><div class="tool-row"><button data-sample="2">使用 .bin 样例</button><button data-sample="0">已有版本（重复）</button><button id="badFile">非法文件名</button></div><label class="tool-label" for="failureScenario">上传 / 提交结果</label><select id="failureScenario"><option value="normal">正常</option><option value="upload">上传失败</option><option value="submit">提交失败</option></select>`:''}
<label class="tool-label" for="backendScenario">后端摘要演示响应</label><select id="backendScenario"><option value="auto">创建后自动返回样例结果</option><option value="hold">摘要暂不返回（可先创建）</option><option value="fail">后端未取得摘要</option></select>${detail?'<div class="tool-row"><button id="returnDigest">模拟返回当前文件摘要</button></div>':''}
${state.context==='list'?`<label class="tool-label">既有权限的差异演示</label><div class="tool-row"><button id="permissionToggle">${state.readOnly?'恢复创建权限':'切为仅查看'}</button></div>`:''}
<label class="tool-label">APP 下载后结果模拟（非 APP 页面）</label><p class="hint">完整下载后的业务结果；不模拟设备传输、CRC 或真实接口。</p><label class="tool-label" for="appGeneration">APP / 接口</label><select id="appGeneration"><option value="new">新 APP（按文件策略演示）</option><option value="old">旧 APP · 旧接口</option></select><label class="tool-label" for="appRecord">下载文件</label><select id="appRecord">${rows.map(r=>`<option value="${r.id}">${esc(r.version)} / ${methodName(r.method)}</option>`).join('')}</select><label class="tool-label" for="authScenario">新接口鉴权</label><select id="authScenario"><option value="ok">鉴权通过</option><option value="fail">鉴权未通过</option></select><label class="tool-label" for="appOutcome">校验输入场景</label><select id="appOutcome"><option value="same">完整文件与摘要一致</option><option value="mismatch">完整文件摘要不一致</option><option value="missing">必要摘要缺失</option><option value="invalid">必要摘要非法</option><option value="unknown">未知算法</option></select><div class="tool-row"><button id="runApp" class="primary">演示下载后结果</button></div><div id="appResult" class="result neutral" role="status">选择场景后演示；不会发起真实升级。</div>`;
if(create){$('#failureScenario').value=state.failure;$('#failureScenario').onchange=e=>state.failure=e.target.value;$$('[data-sample]').forEach(b=>b.onclick=()=>{const f=fixtures[+b.dataset.sample];selectFile(new File([f.content],f.name,{type:'application/octet-stream'}));});$('#badFile').onclick=()=>selectFile(new File(['demo'],'固件包.bin'));}
$('#backendScenario').value=state.backend;$('#backendScenario').onchange=e=>state.backend=e.target.value;if(detail)$('#returnDigest').onclick=()=>returnBackendDigest(rows.find(r=>r.id===state.editing));if($('#permissionToggle'))$('#permissionToggle').onclick=()=>{state.readOnly=!state.readOnly;renderList();renderTools();};
$('#appGeneration').value=state.appGeneration;$('#appGeneration').onchange=e=>{state.appGeneration=e.target.value;syncAppControls();};$('#appRecord').value=rows.some(r=>r.id===state.appRecord)?state.appRecord:rows[0].id;$('#appRecord').onchange=e=>{state.appRecord=e.target.value;syncAppControls();};$('#authScenario').value=state.auth;$('#authScenario').onchange=e=>state.auth=e.target.value;$('#appOutcome').value=state.appOutcome;$('#appOutcome').onchange=e=>state.appOutcome=e.target.value;syncAppControls();$('#runApp').onclick=runAppResult;
}
function syncAppControls(){const r=rows.find(r=>r.id===$('#appRecord').value);const disabled=state.appGeneration==='old'||r?.method==='NONE';$('#authScenario').disabled=disabled;$('#appOutcome').disabled=disabled;}
function runAppResult(){const r=rows.find(r=>r.id===$('#appRecord').value);const el=$('#appResult');let text='',kind='neutral';if(state.appGeneration==='old')text=r.method==='NONE'?'旧 APP → 旧接口 / 旧存储桶裸链，无包校验和下载 token 验证；持有 URL 即可下载。':'旧 APP 继续旧接口；所选文件配置为新接口 / 新存储桶。具体资源可见性与兼容交互由技术方案明确，此处不假定旧接口能下载新桶文件。';else if(r.method==='NONE'){text='无需校验 → 旧版接口 / 旧存储桶裸链，无包校验和下载 token 验证；持有 URL 即可下载，继续既有流程。';kind='neutral';}else if(state.auth==='fail'){text='新版接口 / 新存储桶下载 token 验证未通过 → 不能下载成功，不进入包校验成功路径。';kind='bad';}else if(state.appOutcome==='unknown'){text='完整下载后收到未知算法 → 不能按无需校验放行，停止本次升级并反馈无法校验。';kind='bad';}else if(['missing','invalid'].includes(state.appOutcome)||!r.digest){text=`完整下载后${state.appOutcome==='invalid'?'所需摘要非法':'缺少有效摘要'} → 停止本次升级并反馈无法校验；保留 ${r.method}，不降级为无需校验。`;kind='bad';}else if(state.appOutcome==='mismatch'){text=`完整下载后 ${r.method} 比对不一致 → 停止本次升级；反馈「固件文件校验失败，无法继续升级」。`;kind='bad';}else{text=`完整下载后 ${r.method} 比对一致 → 继续既有升级流程。`;kind='good';}el.className=`result ${kind}`;el.textContent=`演示结果：${text}`;}
function setPane(p){state.pane=p;document.body.dataset.mobilePane=p;$$('[data-pane]').forEach(b=>b.classList.toggle('active',b.dataset.pane===p));if(p==='product'&&$('.drawer'))showDrawerPosition();}
$$('[data-pane]').forEach(b=>b.onclick=()=>setPane(b.dataset.pane));$$('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.drawer'))closeDrawer();});
function loadRoute(){const params=new URLSearchParams(location.search);const view=params.get('view');switchTab(view==='virtual'||view==='members'?'virtual':'firmware');if(view==='create')openCreate();else if(view==='detail')openDetail(params.get('id')||'f2');else if(view==='members')openMembers();const n=location.hash.replace('#note','');if(noteDefs[n])setTimeout(()=>selectNote(n,true),80);}
loadRoute();
